export const SCRIPTS: { code: string; exports: string[] }[] = [{"code":"\n  function togglePost(id) {\n    const extra      = document.getElementById(id + '-extra');\n    const btn        = document.getElementById(id + '-btn');\n    const card       = btn.closest('.post-card');\n    const imgTrigger = card.querySelector('.post-image-link');\n    const isOpen     = extra.classList.contains('open');\n\n    extra.classList.toggle('open', !isOpen);\n    btn.classList.toggle('open',   !isOpen);\n\n    const arrow = btn.querySelector('.btn-arrow');\n    btn.childNodes[0].textContent = isOpen ? 'Read More ' : 'Show Less ';\n    arrow.textContent             = isOpen ? '→' : '↑';\n\n    btn.setAttribute('aria-expanded',         String(!isOpen));\n    if (imgTrigger) imgTrigger.setAttribute('aria-expanded', String(!isOpen));\n  }\n\n  // Keyboard support on clickable images\n  document.querySelectorAll('.post-image-link').forEach(el => {\n    el.addEventListener('keydown', e => {\n      if (e.key === 'Enter' || e.key === ' ') {\n        e.preventDefault();\n        el.click();\n      }\n    });\n  });\n\n  function initIndustrySummaries() {\n    document.querySelectorAll('.industry-card-body').forEach(function(body) {\n      const summary = body.querySelector('p');\n      if (!summary) return;\n\n      const featureList = body.querySelector('.industry-features');\n      const card = body.closest('.industry-card');\n      summary.classList.add('industry-summary');\n      if (featureList) featureList.classList.add('industry-hidden');\n\n      const toggle = document.createElement('button');\n      toggle.type = 'button';\n      toggle.className = 'industry-toggle';\n      toggle.setAttribute('aria-expanded', 'false');\n      toggle.innerHTML = 'See more details <span class=\"industry-toggle-arrow\">→</span>';\n\n      toggle.addEventListener('click', function() {\n        if (card && card.id === 'healthcare') {\n          window.location.href = 'healthcare-life-sciences.html';\n          return;\n        }\n\n        if (card && card.id) {\n          window.location.href = 'industry-detail.html?industry=' + encodeURIComponent(card.id);\n          return;\n        }\n\n        const isOpen = summary.classList.toggle('open');\n        if (featureList) featureList.classList.toggle('open', isOpen);\n        if (card) card.classList.toggle('expanded', isOpen);\n        toggle.classList.toggle('open', isOpen);\n        toggle.innerHTML = isOpen\n          ? 'Show less details <span class=\"industry-toggle-arrow\">↑</span>'\n          : 'See more details <span class=\"industry-toggle-arrow\">→</span>';\n        toggle.setAttribute('aria-expanded', String(isOpen));\n      });\n\n      const ctaButton = body.querySelector('.industry-cta');\n      if (ctaButton) {\n        body.insertBefore(toggle, ctaButton);\n      } else {\n        body.appendChild(toggle);\n      }\n    });\n  }\n\n  initIndustrySummaries();\n","exports":["togglePost","initIndustrySummaries"]}];
